//! Regenerates the built-in `islands-dark` and `islands-light` themes from the
//! New UI "Islands" theme files of the IntelliJ Platform Community repository
//! (Apache-2.0), through the importer of this crate.
//!
//! ```text
//! cargo run -p themes --example builtin_islands -- <checkout> <commit> [<out dir>]
//! ```
//!
//! `<checkout>` is a checkout of https://github.com/JetBrains/intellij-community
//! (a sparse checkout of the files listed in [`FILES`] is enough), `<commit>`
//! its commit id, written into the header of the generated files. The output
//! goes to `crates/platform/themes/themes/` unless `<out dir>` is given. The
//! steps are described in docs/theme-mapping.md ("Built-in themes").

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use themes::import::{Imported, Library};

/// Files read from the checkout. The first two are imported; the others
/// supply parent themes, editor schemes and the Python attributes.
const FILES: &[&str] = &[
    "platform/platform-resources/src/themes/islands/ManyIslandsDark.theme.json",
    "platform/platform-resources/src/themes/islands/ManyIslandsLight.theme.json",
    "platform/platform-resources/src/themes/expUI/expUI_dark.theme.json",
    "platform/platform-resources/src/themes/expUI/expUI_light.theme.json",
    "platform/platform-resources/src/themes/expUI/expUI_light_with_light_header.theme.json",
    "platform/platform-resources/src/themes/darcula.theme.json",
    "platform/platform-resources/src/themes/intellijlaf.theme.json",
    "platform/platform-resources/src/themes/islands/IslandSchemeDark.xml",
    "platform/platform-resources/src/themes/expUI/expUI_lightScheme.xml",
    "platform/platform-resources/src/DefaultColorSchemesManager.xml",
    "python/pluginResources/colorSchemes/PythonDarcula.xml",
    "python/pluginResources/colorSchemes/PythonDefault.xml",
];

/// Imported theme name, id and display name of the built-in theme.
const OUTPUTS: &[(&str, &str, &str, &str)] = &[
    (
        "Islands Dark",
        "islands-dark",
        "Islands Dark",
        "Default dark theme (New UI with islands)",
    ),
    (
        "Islands Light",
        "islands-light",
        "Islands Light",
        "Default light theme (New UI with islands)",
    ),
];

fn header(source: &str, commit: &str) -> String {
    let mut out = String::new();
    out.push_str("# Generated by `cargo run -p themes --example builtin_islands`; do not edit\n");
    out.push_str("# by hand. Colours come from the IntelliJ Platform Community theme files\n");
    out.push_str("# (Apache-2.0, see NOTICE), https://github.com/JetBrains/intellij-community\n");
    out.push_str(&format!("# at commit {commit}, imported from {source}\n"));
    out.push_str("# with its parent themes, editor schemes and the Python attributes:\n");
    for file in FILES {
        out.push_str(&format!("#   {file}\n"));
    }
    out.push_str("# Roles these files do not define, metrics and fonts come from the\n");
    out.push_str("# pyoxide-dark and pyoxide-light themes.\n\n");
    out
}

fn run(checkout: &Path, commit: &str, out_dir: &Path) -> Result<(), String> {
    let mut library = Library::new();
    for (i, file) in FILES.iter().enumerate() {
        let path = checkout.join(file);
        library
            .add_path(&path, i < 2)
            .map_err(|e| format!("{}: {e}", path.display()))?;
    }
    for skipped in library.skipped() {
        eprintln!("skipped {}: {}", skipped.path, skipped.reason);
    }
    let imported: Vec<Imported> = library.import_all();
    for (name, id, display, description) in OUTPUTS {
        let item = imported
            .iter()
            .find(|i| i.theme.name == *name)
            .ok_or_else(|| format!("{name} was not imported"))?;
        println!("{}", item.report.render(false));
        let mut theme = item.theme.clone();
        theme.id = (*id).to_owned();
        theme.name = (*display).to_owned();
        theme.author = None;
        theme.description = Some((*description).to_owned());
        let source = FILES
            .iter()
            .find(|f| f.contains(&format!("ManyIslands{}", &name["Islands ".len()..])))
            .copied()
            .unwrap_or(FILES[0]);
        let text = header(source, commit) + &theme.to_file().to_toml();
        let path = out_dir.join(format!("{id}.toml"));
        std::fs::write(&path, text).map_err(|e| format!("{}: {e}", path.display()))?;
        println!("wrote {}", path.display());
    }
    Ok(())
}

fn main() -> ExitCode {
    let mut args = std::env::args().skip(1);
    let (Some(checkout), Some(commit)) = (args.next(), args.next()) else {
        eprintln!("usage: builtin_islands <intellij-community checkout> <commit> [<out dir>]");
        return ExitCode::from(2);
    };
    let out_dir = args
        .next()
        .map(PathBuf::from)
        .unwrap_or_else(|| Path::new(env!("CARGO_MANIFEST_DIR")).join("themes"));
    match run(Path::new(&checkout), &commit, &out_dir) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
